        sortedNodes = []
        self.inorderTraversal(root, sortedNodes)
        left, right = 0, len(sortedNodes) - 1
        while left < right:
            currentSum = sortedNodes[left].val + sortedNodes[right].val
            if currentSum == k:
                return True
            elif currentSum < k:
                left += 1
            else:
                right -= 1
        return False

