#include <algorithm>

using namespace std;

vector<int> tallestBillboard(vector<int>& rods) {
    int n = rods.size();
    int totalLength = accumulate(rods.begin(), rods.end(), 0);
    vector<vector<int>> dp(n + 1, vector<int>(totalLength + 1, -1));
    dp[0][0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= totalLength; j++) {
            dp[i][j] = dp[i - 1][j];
            if (rods[i - 1] <= j) dp[i][j] = max(dp[i][j], dp[i - 1][j - rods[i - 1]] + rods[i - 1]);
            if (rods[i - 1] <= totalLength - j) dp[i][j] = max(dp[i][j], dp[i - 1][j + rods[i - 1]]);
        }
    }

    vector<int> result;
    int i = n, j = 0;
    while (i > 0) {
        if (dp[i][j] == dp[i - 1][j]) {
            i--;
        } else if (rods[i - 1] <= j && dp[i][j] == dp[i - 1][j - rods[i - 1]] + rods[i - 1]) {
            result.push_back(rods[i - 1]);
            j -= rods[i - 1];
            i--;
        } else {
            result.push_back(rods[i - 1]);
            j += rods[i - 1];
            i--;
        }
    }

    return result;
}

