public boolean canFinish(int numCourses, int[][] prerequisites) {
    // Create a graph to represent the courses and their prerequisites
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < numCourses; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] prerequisite : prerequisites) {
        graph.get(prerequisite[1]).add(prerequisite[0]);
    }

    // Use a depth-first search to check for cycles in the graph
    boolean[] visited = new boolean[numCourses];
    boolean[] onStack = new boolean[numCourses];
    for (int i = 0; i < numCourses; i++) {
        if (!visited[i] && hasCycle(graph, i, visited, onStack)) {
            return false;
        }
    }
    return true;
}

private boolean hasCycle(List<List<Integer>> graph, int node, boolean[] visited, boolean[] onStack) {
    visited[node] = true;
    onStack[node] = true;
    for (int neighbor : graph.get(node)) {
        if (!visited[neighbor]) {
            if (hasCycle(graph, neighbor, visited, onStack)) {
                return true;
            }
        } else if (onStack[neighbor]) {
            return true;
        }
    }
    onStack[node] = false;
    return false;
}

