    public int maxGreatness(int[] nums) {
        Arrays.sort(nums);
        int greatness = 0;
        for (int i = 1; i < nums.length; ++i) {
            if (nums[i - 1] < nums[i]) {
                int temp = nums[i - 1];
                nums[i - 1] = nums[i];
                nums[i] = temp;
                ++greatness;
            }
        }
        return greatness;
    }

    public int maxIntervals(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> a[0] - b[0]);
        int maxIntervals = 0;
        int end = Integer.MIN_VALUE;
        for (int[] interval : intervals) {
            if (interval[0] >= end) {
                ++maxIntervals;
                end = interval[1];
            }
        }
        return maxIntervals;
    }
}

