    if (x == target) return 0;
    if (target == 1) return 1;
    if (x > target) return Math.min(2 * target - 1, 2 * (x - target));

    int k = 0;
    long p = x;
    while (p < target) {
        k++;
        p *= x;
    }

    int ans = Integer.MAX_VALUE;
    long d = 1;

    for (int i = k - 1; i >= 0; i--) {
