def calculateMinimumHP(grid):
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]

    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if i == m - 1 and j == n - 1:
                dp[i][j] = max(1, 1 - grid[i][j])
            elif i == m - 1:
                dp[i][j] = max(1, dp[i][j + 1] - grid[i][j])
            elif j == n - 1:
